SELECT 


ORDER BY sr.reserve_date DESC, sr.create_time DESC
LIMIT #{query.offset}, #{query.limit}

SELECT 

WHERE sr.seat_id = #{seatId}
  AND sr.reserve_date = #{date}
  AND sr.status IN ('WAITING', 'SEATED')
LIMIT 1

SELECT 

WHERE sr.user_id = #{userId}
  AND sr.reserve_date = #{date}
  AND sr.status IN ('WAITING', 'SEATED')
LIMIT 1
